export interface GalleryImage {
  src: string;
  titleKo: string;
  titleEn: string;
  descKo: string;
  descEn: string;
  tagsKo?: string[];
  tagsEn?: string[];
  deckIds?: string[];
  storyKo?: string;
  storyEn?: string;
  sceneKo?: string;
  sceneEn?: string;
  cardMeaningKo?: string;
  cardMeaningEn?: string;
}

export interface GalleryMusic {
  src: string;
  titleKo: string;
  titleEn: string;
  descKo: string;
  descEn: string;
  usedIn: string;
}

export interface GalleryDeck {
  key: string;
  labelKo: string;
  labelEn: string;
  storyKo: string;
  storyEn: string;
}

const withDefaultTags = (images: GalleryImage[], tagsKo: string[], tagsEn: string[]): GalleryImage[] =>
  images.map((image) => ({
    ...image,
    tagsKo: image.tagsKo ?? tagsKo,
    tagsEn: image.tagsEn ?? tagsEn,
  }));

const newestAlphaFirst = (images: GalleryImage[]): GalleryImage[] =>
  [...images].sort((left, right) => Number(left.src.includes('/legacy/')) - Number(right.src.includes('/legacy/')));

